{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 3,
      "text_ar": "لكن اترك باروخ هنا إلى أن أتكلم معه.",
      "verse": 16
    },
    {
      "chapter": 3,
      "text_ar": "ولما قال هذه الأمور، ترك الرب إرميا وصعد إلى السماء.",
      "verse": 17
    },
    {
      "chapter": 3,
      "text_ar": "أما إرميا وباروخ فدكلا المكان المقدس، وأخذا آنية خدمة الهيكل واستودعاها الأرض كما أمرهما الرب.",
      "verse": 18
    },
    {
      "chapter": 3,
      "text_ar": "وفي الحال ابتلعتها الأرض.",
      "verse": 19
    },
    {
      "chapter": 3,
      "text_ar": "وجلس كلاهما وبكيا.",
      "verse": 20
    }
  ]
}
